package com.jnapanam.sportszone.membership.controller; import com.jnapanam.sportszone.membership.dto.*; import com.jnapanam.sportszone.membership.service.MembershipService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/memberships") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')") public class AdminMembershipController{private final MembershipService service;public AdminMembershipController(MembershipService s){service=s;}@GetMapping("/plans") public List<MembershipPlanResponse> plans(){return service.allPlans();}@PostMapping("/plans") @ResponseStatus(HttpStatus.CREATED) public MembershipPlanResponse create(@Valid @RequestBody MembershipPlanRequest r){return service.create(r);}@PutMapping("/plans/{id}") public MembershipPlanResponse update(@PathVariable UUID id,@Valid @RequestBody MembershipPlanRequest r){return service.update(id,r);}@PatchMapping("/plans/{id}/status") public MembershipPlanResponse status(@PathVariable UUID id,@Valid @RequestBody PlanStatusRequest r){return service.status(id,r);}@GetMapping public List<CustomerMembershipResponse> list(){return service.allMemberships();}@PatchMapping("/{id}/status") public CustomerMembershipResponse action(@PathVariable UUID id,@Valid @RequestBody MembershipActionRequest r){return service.adminAction(id,r);}}
